const contract = $('PDF Vector - Analyze Contract').item.json.data;
const summary = $input.first().json.markdown;
const fileName = $('Google Drive Trigger').item.json.name;

// Start with AI-detected risks
const risks = contract.riskFlags || [];
let highRisks = risks.filter(r => r.severity === 'High').length;
let mediumRisks = risks.filter(r => r.severity === 'Medium').length;

const additionalRisks = [];

// === USAGE RIGHTS CHECKS ===
if (contract.usageRights?.isPerpetual) {
  additionalRisks.push({ risk: 'Perpetual usage rights granted — content licensed to brand forever with no expiry', severity: 'High', clause: 'Usage Rights' });
  highRisks++;
}
if (!contract.usageRights?.isPerpetual && contract.usageRights?.durationMonths > 24) {
  additionalRisks.push({ risk: `Usage rights duration ${contract.usageRights.durationMonths} months — unusually long, consider negotiating to 12 months`, severity: 'Medium', clause: 'Usage Rights' });
  mediumRisks++;
}
if (contract.usageRights?.whitelistingIncluded || contract.usageRights?.paidMediaRights) {
  additionalRisks.push({ risk: 'Whitelisting / paid media rights granted — verify this was priced as an add-on fee, not included in base rate', severity: 'High', clause: 'Usage Rights / Paid Media' });
  highRisks++;
}

// === KILL FEE CHECKS ===
if (!contract.killFee?.exists) {
  additionalRisks.push({ risk: 'No kill fee — brand can cancel campaign with zero compensation to creator after work has begun', severity: 'High', clause: 'Termination / Kill Fee' });
  highRisks++;
}

// === EXCLUSIVITY CHECKS ===
if (contract.exclusivityTerms?.exists) {
  if (contract.exclusivityTerms.isBroadCategory) {
    additionalRisks.push({ risk: `Broad category exclusivity — blocks all brands in the ${contract.productCategory} category, not just named competitors`, severity: 'High', clause: 'Exclusivity' });
    highRisks++;
  } else if (contract.exclusivityTerms.durationDays > 90) {
    additionalRisks.push({ risk: `Exclusivity window is ${contract.exclusivityTerms.durationDays} days — over 90 days significantly limits creator income`, severity: 'High', clause: 'Exclusivity' });
    highRisks++;
  } else if (contract.exclusivityTerms.durationDays > 60) {
    additionalRisks.push({ risk: `Exclusivity window is ${contract.exclusivityTerms.durationDays} days — consider negotiating to 30–60 days`, severity: 'Medium', clause: 'Exclusivity' });
    mediumRisks++;
  }
}

// === APPROVAL PROCESS CHECKS ===
if (!contract.approvalWindowDays || contract.approvalWindowDays === 0) {
  additionalRisks.push({ risk: 'No approval window specified — brand can delay content approval indefinitely, blocking posting and payment', severity: 'Medium', clause: 'Approval Process' });
  mediumRisks++;
}

// === REVISION ROUNDS CHECKS ===
if (!contract.revisionRounds || contract.revisionRounds < 2) {
  additionalRisks.push({ risk: `Only ${contract.revisionRounds || 0} revision round(s) specified — standard is 2, less creates friction if brand feedback is extensive`, severity: 'Medium', clause: 'Revision Rounds' });
  mediumRisks++;
}

// === FTC DISCLOSURE CHECK ===
if (!contract.ftcDisclosureRequired) {
  additionalRisks.push({ risk: 'FTC disclosure requirements not mentioned in contract — creator still legally required to disclose; recommend adding explicit clause', severity: 'Medium', clause: 'FTC / Compliance' });
  mediumRisks++;
}

// === Combine all risks ===
const allRisks = [...risks, ...additionalRisks];

// Format parties
const partiesList = contract.parties
  ? contract.parties.map(p => `${p.name} (${p.role})`).join(', ')
  : 'Not specified';

// Format deliverables
const deliverablesList = contract.contentDeliverables && contract.contentDeliverables.length
  ? contract.contentDeliverables.map(d => `${d.quantity || 1}x ${d.type} (${d.platform || 'platform TBD'}) by ${d.deadline || 'TBD'}`).join(', ')
  : 'Not specified';

// Format usage rights
const usagePlatforms = contract.usageRights?.platforms?.join(', ') || 'Not specified';
const usageDuration = contract.usageRights?.isPerpetual
  ? '⚠️ PERPETUAL'
  : contract.usageRights?.rawDurationText || (contract.usageRights?.durationMonths ? `${contract.usageRights.durationMonths} months` : 'Not specified');

// Format exclusivity
const exclusivitySummary = contract.exclusivityTerms?.exists
  ? `${contract.exclusivityTerms.durationDays || '?'} days — ${contract.exclusivityTerms.competitorScope || 'scope unspecified'}`
  : 'None';

// Format kill fee
const killFeeSummary = contract.killFee?.exists
  ? `${contract.killFee.percentage || '?'}% — ${contract.killFee.triggerConditions || 'conditions unspecified'}`
  : '⚠️ NONE';

// Format risks list
const risksList = allRisks.map(r => `[${r.severity}] ${r.risk}`).join('\n') || 'No significant risks identified';

// Determine overall review status
let reviewStatus = 'Ready for Signature';
if (highRisks > 0) reviewStatus = 'Requires Legal Review';
else if (mediumRisks >= 2) reviewStatus = 'Review Recommended';

// Health/wellness brand flag — triggers Brief Strategist callout
const healthWellnessBrands = ['thorne', 'lmnt', 'armra', 'equip', 'hume health', 'hume'];
const brandLower = (contract.brandName || '').toLowerCase();
const needsBriefStrategistReview = contract.isHealthWellness
  || ['Health & Wellness', 'Fitness & Sports', 'Food & Beverage'].includes(contract.productCategory)
  || healthWellnessBrands.some(b => brandLower.includes(b));

return [{
  json: {
    ...contract,
    executiveSummary: summary,
    partiesList,
    deliverablesList,
    usagePlatforms,
    usageDuration,
    exclusivitySummary,
    killFeeSummary,
    risksList,
    highRiskCount: highRisks,
    mediumRiskCount: mediumRisks,
    reviewStatus,
    needsBriefStrategistReview,
    fileName,
    fileId: $('Google Drive Trigger').item.json.id,
    processedAt: new Date().toISOString()
  }
}];

